package vn.venusgiti.vticket;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.*;
import java.util.*;
import vn.venusgiti.vticket.Domain.*;
@Service @Transactional
public class SmileSyncQueue {
 private final SmileProperties props;private final SmileJobs jobs;private final TicketStock stock;private final TicketBatches batches;private final Products products;private final Audits audits;private final Clock clock;
 SmileSyncQueue(SmileProperties p,SmileJobs j,TicketStock s,TicketBatches b,Products products,Audits a,Clock c){props=p;jobs=j;stock=s;batches=b;this.products=products;audits=a;clock=c;}
 public void created(TicketBatch batch){if(props.enabled())enqueue(batch,"system");}
 private void enqueue(TicketBatch b,String actor){BookingService.require("VTICKET".equals(b.source),"Lô nhập từ Smile đã có mã nguồn, không tạo lại trên Smile");BookingService.require(!SmileProperties.blank(b.smileTicketTypeCode),"Điền PkgCode Smile trước khi tạo/đồng bộ lô");var existing=jobs.findById(b.id).orElse(null);BookingService.require(existing==null||!"SYNCED".equals(existing.state),"Lô đã đồng bộ; không thay đổi ánh xạ mã");BookingService.require(existing==null||!"SYNCING".equals(existing.state)||!clock.instant().isBefore(existing.leaseUntil),"Lô đang được đồng bộ, vui lòng chờ");var rows=stock.findByBatchIdOrderByCodeAsc(b.id);BookingService.require(!rows.isEmpty()&&rows.stream().allMatch(c->c.state==StockState.AVAILABLE),"Chỉ đồng bộ lô chưa có mã đang giữ/đã bán/đã dùng; cần đối soát lô cũ trước");if(b.smileCodeMapping==null)b.smileCodeMapping=props.codeMapping();var j=existing==null?new SmileJob():existing;j.batchId=b.id;j.state="PENDING";j.createdAt=existing==null?clock.instant():j.createdAt;j.nextAttemptAt=clock.instant();j.lastError=null;j.leaseUntil=null;jobs.save(j);b.active=false;b.smileSyncState="PENDING";audit(actor,"SMILE_QUEUED",b.code);}
 public TicketBatch configureAndQueue(String id,String pkgCode,String typeName,String actor){BookingService.require(props.enabled(),"Chưa bật tích hợp Smile");var b=batches.findById(id).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.NOT_FOUND));products.lockId(b.productId).orElseThrow();BookingService.require(!jobs.existsById(id)||Objects.equals(b.smileTicketTypeCode,pkgCode.strip()),"Lô đã có lần đồng bộ, không đổi PkgCode trước khi đối soát");b.smileTicketTypeCode=pkgCode.strip();b.smileTicketTypeName=typeName==null?null:typeName.strip();enqueue(b,actor);return b;}
 public record Claim(String batchId,String attemptId,SmileGateway.Batch payload) {}
 public Claim claim(String id){var b=batches.findById(id).orElseThrow();products.lockId(b.productId).orElseThrow();var job=jobs.lockId(id).orElse(null);if(job==null||"SYNCED".equals(job.state)||("SYNCING".equals(job.state)&&clock.instant().isBefore(job.leaseUntil)))return null;var rows=stock.findByBatchIdOrderByCodeAsc(id);BookingService.require(rows.stream().allMatch(c->c.state==StockState.AVAILABLE),"Lô đã phát sinh giao dịch, không thể đồng bộ");job.state="SYNCING";job.attemptId=UUID.randomUUID().toString();job.attempts++;job.leaseUntil=clock.instant().plusSeconds(900);b.smileSyncState="SYNCING";var codes=rows.stream().map(c->{BookingService.require(c.smileSerial!=null&&c.smileBarcode!=null,"Lô chưa đủ Seri/barcode, cần bổ sung mã trước");return "FIELD_NAMES".equals(b.smileCodeMapping)?new SmileGateway.Code(c.id,c.smileBarcode,c.smileSerial):new SmileGateway.Code(c.id,c.smileSerial,c.smileBarcode);}).toList();return new Claim(id,job.attemptId,new SmileGateway.Batch(b.code,b.smileTicketTypeCode,b.validFrom,b.validUntil,Boolean.TRUE.equals(b.smileIsWeekday),Boolean.TRUE.equals(b.smileIsChild),codes));}
 public void complete(Claim claim,List<SmileGateway.Synced> result){var b=batches.findById(claim.batchId()).orElseThrow();products.lockId(b.productId).orElseThrow();var job=jobs.lockId(claim.batchId()).orElseThrow();if(!Objects.equals(job.attemptId,claim.attemptId()))return;var expected=new HashSet<>(claim.payload().codes().stream().map(SmileGateway.Code::stockId).toList());BookingService.require(result.size()==expected.size()&&expected.equals(new HashSet<>(result.stream().map(SmileGateway.Synced::stockId).toList())),"Kết quả Smile thiếu/trùng mã");for(var row:result){var code=stock.findById(row.stockId()).orElseThrow();BookingService.require(Objects.equals(row.gateBarcode(),claim.payload().codes().stream().filter(c->c.stockId().equals(row.stockId())).findFirst().orElseThrow().barcode())&&row.seqNo()!=null,"Ánh xạ phản hồi Smile không hợp lệ");code.smileGateBarcode=row.gateBarcode();code.smileSeqNo=row.seqNo();}job.state="SYNCED";job.syncedAt=clock.instant();job.lastError=null;job.leaseUntil=null;b.smileSyncState="SYNCED";b.smileSyncedAt=job.syncedAt;audit("smile","SMILE_SYNCED",b.code);}
 public void fail(Claim claim,String error){var b=batches.findById(claim.batchId()).orElseThrow();products.lockId(b.productId).orElseThrow();var j=jobs.lockId(claim.batchId()).orElseThrow();if(!Objects.equals(j.attemptId,claim.attemptId()))return;j.state="FAILED";j.lastError=error.substring(0,Math.min(500,error.length()));j.nextAttemptAt=clock.instant().plusSeconds(Math.min(3600,30L*(1L<<Math.min(j.attempts,6))));j.leaseUntil=null;batches.findById(j.batchId).orElseThrow().smileSyncState="FAILED";audit("smile","SMILE_FAILED",j.batchId);}
 @Transactional(readOnly=true) public List<SmileJob> list(){return jobs.findTop200ByOrderByCreatedAtDesc();}
 private void audit(String actor,String action,String target){var a=new Audit();a.happenedAt=clock.instant();a.actor=actor;a.action=action;a.target=target;audits.save(a);}
}
